import bisect

def _merge(intervals):
    ivs = [[s, e] for s, e in intervals if s < e]
    ivs.sort()
    merged = []
    for s, e in ivs:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1][1] = e
        else:
            merged.append([s, e])
    return merged

def subtract(a, b):
    a_merged = _merge(a)
    b_merged = _merge(b)

    if not a_merged:
        return []
    if not b_merged:
        return [list(iv) for iv in a_merged]

    b_starts = [iv[0] for iv in b_merged]

    result = []
    for a_start, a_end in a_merged:
        cur = a_start
        # find first b interval whose end could matter: b_start could be less than a_end
        # find index of first b interval with start >= a_start (approx) - but need ones ending after a_start too
        idx = bisect.bisect_right(b_starts, a_start) - 1
        if idx < 0:
            idx = 0
        # move idx forward to skip b intervals fully before cur
        n = len(b_merged)
        while idx < n and b_merged[idx][1] <= cur:
            idx += 1
        while idx < n and b_merged[idx][0] < a_end:
            bs, be = b_merged[idx]
            if be <= cur:
                idx += 1
                continue
            if bs >= a_end:
                break
            if bs > cur:
                result.append([cur, min(bs, a_end)])
            cur = max(cur, be)
            if cur >= a_end:
                break
            idx += 1
        if cur < a_end:
            result.append([cur, a_end])

    # merge touching pieces in result (shouldn't normally be needed but safe)
    final = []
    for s, e in result:
        if final and s <= final[-1][1]:
            if e > final[-1][1]:
                final[-1][1] = e
        else:
            final.append([s, e])
    return final

